"""Origin framing and evidence audit extension.

Parses consecutive HTTP/1.1 requests from a compressed channel capture,
materializing only bounded head windows while body fingerprints are computed
directly from the rope, and derives the paired provenance diagnostics.
"""
import re
from bisect import bisect_right

from modules.byte_program import (BASE, MOD, ByteWindow, concat_all,
                                  empty_fingerprint, fingerprint, range_hash)

TOKEN = re.compile(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+\Z")
TARGET = re.compile(rb'[\x21-\x7e]+\Z')
FIELD_VALUE = re.compile(rb'[\x20-\x7e\x09]*\Z')
DECIMAL = re.compile(rb'[0-9]+\Z')
HEX = re.compile(rb'[0-9a-fA-F]+\Z')
LINE_LIMIT = 8192
LINE_WINDOW = LINE_LIMIT + 2
BLOCK_LIMIT = 65536
BLOCK_FIELDS = 128
MAX = (1 << 63) - 1
REQUEST_BUDGET = 20000
CHUNK_LINE_BUDGET = 40000
FORBIDDEN_TRAILERS = (b'host', b'content-length', b'transfer-encoding')


class ChannelError(Exception):
    """Uncommitted request terminator: 'syntax' or 'incomplete'."""

    def __init__(self, kind):
        super().__init__(kind)
        self.kind = kind


def fp_bytes(data):
    """Fingerprint object of a literal byte string."""
    value = 0
    for byte in data:
        value = (value * BASE + byte + 1) % MOD
    return {'n': len(data), 'h': '%016x' % value}


def field_block(fields):
    """Fingerprint object of an encoded field block."""
    out = bytearray()
    out += len(fields).to_bytes(8, 'big')
    for name, value in fields:
        out += len(name).to_bytes(8, 'big')
        out += name
        out += len(value).to_bytes(8, 'big')
        out += value
    return fp_bytes(bytes(out))


class CaptureParser:
    """Sequential HTTP/1.1 request reader over one channel capture."""

    def __init__(self, seq, budget):
        self.seq = seq
        self.window = ByteWindow(seq)
        self.total = seq.n
        self.pos = 0
        self.budget = budget

    # -- line level -----------------------------------------------------
    def read_line(self):
        buffer, offset, available = self.window.view(LINE_WINDOW)
        if available <= 0:
            raise ChannelError('incomplete')
        index = buffer.find(b'\n', offset, offset + available)
        if index < 0:
            if available >= LINE_WINDOW:
                raise ChannelError('syntax')
            raise ChannelError('incomplete')
        if index == offset or buffer[index - 1] != 0x0d:
            raise ChannelError('syntax')
        length = index - 1 - offset
        if length > LINE_LIMIT:
            raise ChannelError('syntax')
        content = bytes(buffer[offset:index - 1])
        self.window.advance(index + 1 - offset)
        self.pos = self.window.pos
        return content

    def read_field(self, content):
        colon = content.find(b':')
        if colon <= 0:
            raise ChannelError('syntax')
        name = content[:colon]
        if TOKEN.fullmatch(name) is None:
            raise ChannelError('syntax')
        raw = content[colon + 1:]
        if FIELD_VALUE.fullmatch(raw) is None:
            raise ChannelError('syntax')
        return name, raw.strip(b' \t')

    # -- request level --------------------------------------------------
    def parse(self):
        requests = []
        error = None
        while self.pos < self.total:
            start = self.pos
            try:
                requests.append(self.parse_request(start))
            except ChannelError as exc:
                error = {'kind': exc.kind, 'offset': start}
                break
            self.budget['requests'] += 1
            if self.budget['requests'] > REQUEST_BUDGET:
                raise ValueError('origin request budget')
        return requests, error

    def parse_request(self, start):
        content = self.read_line()
        parts = content.split(b' ')
        if len(parts) != 3:
            raise ChannelError('syntax')
        method, target, version = parts
        if TOKEN.fullmatch(method) is None:
            raise ChannelError('syntax')
        if TARGET.fullmatch(target) is None:
            raise ChannelError('syntax')
        if version != b'HTTP/1.1':
            raise ChannelError('syntax')
        block = len(content) + 2
        if block > BLOCK_LIMIT:
            raise ChannelError('syntax')
        fields = []
        while True:
            content = self.read_line()
            block += len(content) + 2
            if block > BLOCK_LIMIT:
                raise ChannelError('syntax')
            if not content:
                break
            if len(fields) >= BLOCK_FIELDS:
                raise ChannelError('syntax')
            fields.append(self.read_field(content))
        framing, length, host_count, host_value, cl_values, te_count = self.framing(fields)
        body_n, body_h, trailers = self.parse_body(framing, length)
        return (start, self.pos, method, target, host_count, host_value, fields,
                body_n, body_h, trailers, framing)

    @staticmethod
    def framing(fields):
        host_count = 0
        host_value = None
        cl_values = []
        te_count = 0
        te_value = None
        for name, value in fields:
            low = name.lower()
            if low == b'host':
                host_count += 1
                host_value = value
            elif low == b'content-length':
                for member in value.split(b','):
                    member = member.strip(b' \t')
                    if not member or DECIMAL.fullmatch(member) is None:
                        raise ChannelError('syntax')
                    number = int(member)
                    if number > MAX:
                        raise ChannelError('syntax')
                    cl_values.append(number)
            elif low == b'transfer-encoding':
                te_count += 1
                te_value = value
        if te_count:
            if te_count > 1 or cl_values or te_value.lower() != b'chunked':
                raise ChannelError('syntax')
            return 'chunked', 0, host_count, host_value, cl_values, te_count
        if cl_values:
            if any(value != cl_values[0] for value in cl_values):
                raise ChannelError('syntax')
            return 'length', cl_values[0], host_count, host_value, cl_values, te_count
        return 'none', 0, host_count, host_value, cl_values, te_count

    def parse_body(self, framing, length):
        if framing == 'none':
            return 0, 0, []
        if framing == 'length':
            if self.pos + length > self.total:
                raise ChannelError('incomplete')
            span = range_hash(self.seq, self.pos, self.pos + length)
            self.window.advance(length)
            self.pos = self.window.pos
            return span[0], span[1], []
        return self.parse_chunked()

    def parse_chunked(self):
        body_n = 0
        body_h = 0
        while True:
            content = self.read_line()
            self.budget['lines'] += 1
            if self.budget['lines'] > CHUNK_LINE_BUDGET:
                raise ValueError('chunk-size line budget')
            semi = content.find(b';')
            if semi >= 0:
                size_part = content[:semi]
                if FIELD_VALUE.fullmatch(content[semi + 1:]) is None:
                    raise ChannelError('syntax')
            else:
                size_part = content
            if not size_part or HEX.fullmatch(size_part) is None:
                raise ChannelError('syntax')
            value = int(size_part, 16)
            if value > MAX:
                raise ChannelError('syntax')
            if not value:
                return body_n, body_h, self.parse_trailers()
            if self.pos + value > self.total:
                raise ChannelError('incomplete')
            span = range_hash(self.seq, self.pos, self.pos + value)
            body_h = (body_h * pow(BASE, span[0], MOD) + span[1]) % MOD
            body_n += span[0]
            self.window.advance(value)
            self.pos = self.window.pos
            buffer, offset, available = self.window.view(2)
            if available < 2:
                raise ChannelError('incomplete')
            if buffer[offset] != 0x0d or buffer[offset + 1] != 0x0a:
                raise ChannelError('syntax')
            self.window.advance(2)
            self.pos = self.window.pos

    def parse_trailers(self):
        fields = []
        block = 0
        while True:
            content = self.read_line()
            block += len(content) + 2
            if block > BLOCK_LIMIT:
                raise ChannelError('syntax')
            if not content:
                break
            if len(fields) >= BLOCK_FIELDS:
                raise ChannelError('syntax')
            name, value = self.read_field(content)
            if name.lower() in FORBIDDEN_TRAILERS:
                raise ChannelError('syntax')
            fields.append((name, value))


def span_owners(bounds, labels, start, end):
    """Attribution of the raw request span as merged [label, count] pairs."""
    index = bisect_right(bounds, start) - 1
    while index < len(labels) and bounds[index + 1] <= start:
        index += 1
    counts = {}
    order = []
    while index < len(labels) and bounds[index] < end:
        low = bounds[index] if bounds[index] > start else start
        high = bounds[index + 1] if bounds[index + 1] < end else end
        if high > low:
            label = labels[index]
            if label not in counts:
                counts[label] = 0
                order.append(label)
            counts[label] += high - low
        index += 1
    return [(label, counts[label]) for label in order]


def audit_channel(channel, expect, positions, case_records, owner_seen,
                  origin_counts, case_flags, budget):
    """Parse one channel and emit its record with provenance flags."""
    parts = channel['parts']
    labels = [part['case'] for part in parts]
    seqs = [part['data'] for part in parts]
    seq = concat_all(seqs)
    bounds = [0]
    for item in seqs:
        bounds.append(bounds[-1] + item.n)
    parser = CaptureParser(seq, budget)
    requests, error = parser.parse()
    ends = [record[1] for record in requests]
    committed = [bisect_right(ends, bound) for bound in bounds[1:]]
    records = []
    for item in requests:
        (start, end, method, target, host_count, host_value, fields,
         body_n, body_h, trailers, framing) = item
        owners = span_owners(bounds, labels, start, end)
        owner = owners[0][0] if owners else None
        flags = set()
        if owner is None:
            flags.add('unattributed')
        if any(label != owner for label, _ in owners):
            flags.add('mixed_owner')
        if host_count == 0:
            flags.add('missing_host')
        elif host_count > 1:
            flags.add('multiple_host')
        if owner is not None:
            wanted = expect[owner]
            record = case_records[positions[owner]]
            if (method != wanted['method'].encode('ascii')
                    or target != wanted['target'].encode('ascii')):
                flags.add('identity')
            elif host_count != 1 or host_value.lower() != wanted['host'].encode('ascii').lower():
                flags.add('identity')
            seen = owner_seen.get(owner, 0) + 1
            owner_seen[owner] = seen
            if seen > 1:
                flags.add('extra')
            if record['request_frames'] == 0:
                flags.add('unsent')
            index = positions[owner]
            origin_counts[index] += 1
            if 'identity' in flags:
                case_flags[index].add('identity')
            if 'mixed_owner' in flags:
                case_flags[index].add('mixed_origin')
        records.append({
            'start': start,
            'end': end,
            'method': fp_bytes(method),
            'target': fp_bytes(target),
            'host': fp_bytes(host_value.lower()) if host_count == 1 else empty_fingerprint(),
            'host_count': host_count,
            'headers': field_block(fields),
            'body': {'n': body_n, 'h': '%016x' % body_h},
            'trailers': field_block(trailers),
            'framing': framing,
            'owner': owner,
            'owners': owners,
            'flags': sorted(flags),
        })
    return {'name': channel['name'], 'bytes': fingerprint(seq),
            'requests': records, 'committed': committed, 'error': error}


def audit_channels(channels, cases, case_records):
    """Audit all captures and finish the paired case diagnostics."""
    expect = {}
    positions = {}
    for index, case in enumerate(cases):
        expect[case['name']] = case['expect']
        positions[case['name']] = index
    owner_seen = {}
    origin_counts = [0] * len(cases)
    case_flags = [set() for _ in range(len(cases))]
    budget = {'requests': 0, 'lines': 0}
    records = []
    for channel in channels:
        records.append(audit_channel(channel, expect, positions, case_records,
                                     owner_seen, origin_counts, case_flags, budget))
    for index, record in enumerate(case_records):
        flags = case_flags[index]
        count = origin_counts[index]
        frames = record['request_frames']
        if frames > 0 and count == 0:
            flags.add('missing_origin')
        if count > 1:
            flags.add('extra_origin')
        if count > 0 and frames == 0:
            flags.add('unsent_origin')
        record['origin_count'] = count
        record['flags'] = sorted(flags)
    return records
